export class LexError extends Error {
  constructor(reason, line, col) {
    super(reason)
    this.reason = reason
    this.line = line
    this.col = col
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

function isDecDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}
function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}
function isBinDigit(c) {
  return c === '0' || c === '1'
}
function isOctDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}
function isIdentStart(c) {
  return c !== undefined && /[A-Za-z_]/.test(c)
}
function isIdentContinue(c) {
  return c !== undefined && /[A-Za-z0-9_]/.test(c)
}

class Scanner {
  constructor(source) {
    this.chars = Array.from(source)
    this.pos = 0
    this.line = 1
    this.col = 1
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  advance() {
    const ch = this.chars[this.pos]
    this.pos++
    if (ch === '\n') {
      this.line++
      this.col = 1
    } else if (ch === '\t') {
      this.col = 4 * Math.floor((this.col - 1) / 4) + 5
    } else {
      this.col++
    }
    return ch
  }

  here() {
    return { line: this.line, col: this.col }
  }

  textSince(startPos) {
    return this.chars.slice(startPos, this.pos).join('')
