    let count = initialCount
    for (;;) {
      const c = this.peek()
      if (c !== undefined && isDigit(c)) {
        this.advance()
        count++
        continue
      }
      if (c === '_' && count > 0 && isDigit(this.peek(1))) {
        this.advance()
        continue
      }
      break
    }
    return count
  }

