    for (;;) {
      const c = this.peek()
      if (c === undefined) return
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        while (this.peek() !== undefined && this.peek() !== '\n') this.advance()
        continue
