        const esc = this.peek()
        if (esc === undefined) throw new LexError('unterminated string', start.line, start.col)
        switch (esc) {
          case 'n':
            this.advance()
            value += '\n'
            break
          case 't':
            this.advance()
            value += '\t'
            break
          case 'r':
            this.advance()
            value += '\r'
            break
          case '\\':
            this.advance()
            value += '\\'
            break
          case '"':
            this.advance()
            value += '"'
            break
          case '0':
            this.advance()
            value += '\0'
            break
          case 'x': {
            this.advance() // 'x'
            const h1 = this.peek()
            const h2 = this.peek(1)
            if (!isHexDigit(h1) || !isHexDigit(h2)) {
              throw new LexError('invalid escape \\x', backslashPos.line, backslashPos.col)
            }
            this.advance()
            this.advance()
            value += String.fromCharCode(parseInt(h1 + h2, 16))
            break
          }
          case 'u': {
            this.advance() // 'u'
            if (this.peek() !== '{') {
              throw new LexError('invalid escape \\u', backslashPos.line, backslashPos.col)
            }
            this.advance() // '{'
            let hex = ''
            while (this.peek() !== undefined && isHexDigit(this.peek())) hex += this.advance()
            if (hex.length === 0 || this.peek() !== '}') {
              throw new LexError('invalid escape \\u', backslashPos.line, backslashPos.col)
            }
            this.advance() // '}'
            const cp = parseInt(hex, 16)
            if (cp > 0x10ffff) {
              throw new LexError('invalid escape \\u', backslashPos.line, backslashPos.col)
            }
            value += String.fromCodePoint(cp)
            break
          }
          default:
            throw new LexError(`invalid escape \\${esc}`, backslashPos.line, backslashPos.col)
        }
        continue
      }
      value += this.advance()
    }
    return { kind: 'string', text: JSON.stringify(value), line: start.line, col: start.col }
  }

  scanRawString() {
    const start = this.here()
    this.advance() // 'r'
    this.advance() // '"'
    let value = ''
    for (;;) {
      const c = this.peek()
      if (c === undefined) throw new LexError('unterminated string', start.line, start.col)
      if (c === '"') {
        this.advance()
        break
      }
      value += this.advance()
    }
    return { kind: 'rawstring', text: JSON.stringify(value), line: start.line, col: start.col }
  }

  scanPunctOrError() {
    const start = this.here()
    const two = (this.peek() ?? '') + (this.peek(1) ?? '')
    if (TWO_CHAR_PUNCT.has(two)) {
      this.advance()
      this.advance()
      return { kind: 'punct', text: two, line: start.line, col: start.col }
    }
    const c = this.peek()
    if (ONE_CHAR_PUNCT.has(c)) {
      this.advance()
      return { kind: 'punct', text: c, line: start.line, col: start.col }
    }
    this.advance()
    throw new LexError(`unexpected character ${c}`, start.line, start.col)
  }
